        body: `割合とは「ある量が別の量の何倍にあたるか」を表す数です。日常生活でよく使う「何%引き」「○割引」「消費税10%」「打率3割2分5厘」もすべて割合の一種です。

━━━━━━━━━━━━━━━━━━━
■ 割合が使われている場面（身近な例）
━━━━━━━━━━━━━━━━━━━
① スーパーの「3割引セール」→ 定価の70%で買える
② 消費税10%          → 商品代金の1.1倍を払う
③ 野球の打率「.325」   → 10打数で3.25本ヒット（32.5%）
④ 「定員の80%が合格」  → 100人定員なら80人受かる
⑤ 「前年比120%の売上」 → 去年の1.2倍になった

━━━━━━━━━━━━━━━━━━━
■ 3つの量の関係（これが割合の核心！）
━━━━━━━━━━━━━━━━━━━
割合の問題には必ず3つの量が登場します。

・基準量（もとにする量）
　比べる相手、「全体」や「定価」にあたるもの。
　「〇〇の何%か」の「〇〇の」で指される量。

・比較量（比べる量）
　実際に注目している量。「売価」「人数」「増減量」など。

・割合
　基準量に対する比較量の大きさ（小数・%・歩合で表す）。

━━━━━━━━━━━━━━━━━━━
■ 黄金公式（割合の三角形）
━━━━━━━━━━━━━━━━━━━
        ┌────────┐
        │  比較量  │
        └────────┘
      ┌──────┬──────┐
      │ 基準量 │ 割 合 │
      └──────┴──────┘

　▶ 割合　 ＝ 比較量 ÷ 基準量
　▶ 比較量 ＝ 基準量 × 割合
　▶ 基準量 ＝ 比較量 ÷ 割合

求めたいものを三角形で隠すと残りの計算式がわかります。

━━━━━━━━━━━━━━━━━━━
■ 例題で確認（基礎3問）
━━━━━━━━━━━━━━━━━━━
【例1】定価1,200円の商品が840円で売れた。割合はいくらか？
　解：割合 ＝ 840 ÷ 1,200 ＝ 0.7 → 70%（7割）

【例2】定価1,500円の商品を60%の値段で売ると売価はいくら？
　解：比較量 ＝ 1,500 × 0.6 ＝ 900円

【例3】ある商品を750円で売ったら定価の75%だった。定価はいくら？
　解：基準量 ＝ 750 ÷ 0.75 ＝ 1,000円

━━━━━━━━━━━━━━━━━━━
★ もとにする量の見分け方（最重要！）
━━━━━━━━━━━━━━━━━━━
「〇〇の何%・何割か」という文の「〇〇の」の直前の名詞が基準量です。

例：「定価の30%引き」→ 基準量は「定価」
例：「去年の人口の5%増し」→ 基準量は「去年の人口」
例：「全体の何%が合格か」→ 基準量は「全体」

⚠ 要注意：「30%引き」と「30%の値段」は全く違う！
・30%引き → 定価 × (1 − 0.3) ＝ 定価 × 0.7（70%の値段）
・30%の値段 → 定価 × 0.3 のみ（つまり70%引き！）`,
