        body: `比とは「2つ以上の量の相対的な大きさの関係」を表します。割合が「1つの量の大きさ」を表すのに対し、比は「複数の量の関係」を表します。

━━━━━━━━━━━━━━━━━━━
■ 比の基本操作①：最も簡単な整数比
━━━━━━━━━━━━━━━━━━━
両方の数を最大公約数で割ると、最も簡単な整数比になります。

【整数の比】
　12:18 → 最大公約数6で割る → 2:3
　15:25 → 最大公約数5で割る → 3:5
　24:36:60 → 最大公約数12で割る → 2:3:5

【小数の比】
　1.5 : 2 → 両辺×10 → 15:20 → 最大公約数5で割る → 3:4
　0.6 : 0.9 → 両辺×10 → 6:9 → 最大公約数3で割る → 2:3

【分数の比】
　1/2 : 1/3 → 両辺に最小公倍数6を掛ける → 3:2
　3/4 : 5/6 → 両辺に最小公倍数12を掛ける → 9:10
　2/3 : 3/4 : 5/6 → 両辺に最小公倍数12を掛ける → 8:9:10

━━━━━━━━━━━━━━━━━━━
■ 比の基本操作②：逆比
━━━━━━━━━━━━━━━━━━━
a:b の逆比は b:a です（分母と分子を入れ替えるイメージ）。

逆比の例：
　3:4 の逆比 → 4:3
　2:3:5 の逆比 → 1/2 : 1/3 : 1/5 → 最小公倍数30を掛ける → 15:10:6

逆比が使われる場面：
・速さと時間（同じ距離なら「速い人ほど時間が短い」= 反比例）
・仕事量と日数（同じ仕事なら「人数が多いほど日数が少ない」= 反比例）

例）AとBが同じ距離を走る。Aの速さとBの速さが3:4のとき、かかる時間の比は？
　速さが3:4 → 時間は逆比 → 4:3（速い人ほど早く着く）

━━━━━━━━━━━━━━━━━━━
■ 比の基本操作③：比の性質
━━━━━━━━━━━━━━━━━━━
比は「倍数関係」が成り立ちます。
　a:b = ka:kb（両辺に同じ数を掛けても比は変わらない）
　a:b = (a÷k):(b÷k)（両辺を同じ数で割っても変わらない）

比の等式（外項の積 ＝ 内項の積）：
　a:b ＝ c:d のとき、a×d ＝ b×c

例）3:5 ＝ □:20 のとき□はいくつか？
　3×20 ＝ 5×□ → □ ＝ 60÷5 ＝ 12

⚠ 大事な注意：比 a:b と割合 a/(a+b) の違い！
「A:B ＝ 2:3 のとき、Aは全体の2/3か？」→ 誤り！
正しくは A ＝ 全体 × 2/(2+3) ＝ 全体の 2/5 です。
分母は「a+b（合計）」であることを忘れないで。`,
