        figureId: 'lf_sansu_03',
        body: `売買損益は割合の最頻出テーマです。「原価→定価→売価」の流れを完全に理解しましょう。

━━━━━━━━━━━━━━━━━━━
■ 基本の用語
━━━━━━━━━━━━━━━━━━━
・原価（げんか）  ＝ 仕入れた値段（コスト）
・定価（ていか）  ＝ 本来の売り値（ラベルの値段）
・売価（ばいか）  ＝ 実際に売った値段（割引後の値段）
・利益（りえき）  ＝ 売価 − 原価（プラスなら利益、マイナスなら損失）
・割引額        ＝ 定価 − 売価（「引き」で安くなった金額）

━━━━━━━━━━━━━━━━━━━
■ 計算の基本フロー
━━━━━━━━━━━━━━━━━━━
原価 → [利益率を乗せる] → 定価 → [割引] → 売価

定価 ＝ 原価 × (1 ＋ 利益率)
売価 ＝ 定価 × (1 − 割引率)
利益 ＝ 売価 − 原価

━━━━━━━━━━━━━━━━━━━
■ 例題①：基本の売買問題
━━━━━━━━━━━━━━━━━━━
原価800円の商品に40%の利益を見込んで定価をつけ、
定価の25%引きで売った。利益または損失はいくらか？

【解法】
定価 ＝ 800 × (1 ＋ 0.4) ＝ 800 × 1.4 ＝ 1,120円
売価 ＝ 1,120 × (1 − 0.25) ＝ 1,120 × 0.75 ＝ 840円
利益 ＝ 840 − 800 ＝ ＋40円 → 40円の利益

★ 検算：原価に対する利益の割合 ＝ 40 ÷ 800 ＝ 0.05 ＝ 5%

━━━━━━━━━━━━━━━━━━━
■ 例題②：損益率から定価を求める
━━━━━━━━━━━━━━━━━━━
ある商品を定価の2割引で売ったら、原価の10%の利益が出た。
原価は定価の何%か？

【解法】
定価をxとすると
売価 ＝ x × 0.8（2割引）
利益 ＝ 原価 × 0.1（原価の10%）

売価 ＝ 原価 ＋ 利益
x × 0.8 ＝ 原価 × 1.1
原価 ＝ 0.8x ÷ 1.1 ＝ 8x/11

原価の定価に対する割合 ＝ 8/11 ≈ 72.7%
→ 定価は原価の11/8 ＝ 1.375倍 ＝ 137.5%増し（37.5%増し）

━━━━━━━━━━━━━━━━━━━
■ 例題③：2段階割引
━━━━━━━━━━━━━━━━━━━
定価3,000円の商品をまず10%引きにし、
さらにそこから20%引きにした。最終的な売価はいくら？

❌ 誤り：10＋20 ＝ 30%引き → 3,000 × 0.7 ＝ 2,100円
　　※「割引の足し算」はできません！

✓ 正解：
　1回目の割引後 ＝ 3,000 × 0.9 ＝ 2,700円
　2回目の割引後 ＝ 2,700 × 0.8 ＝ 2,160円

　または一発計算：3,000 × 0.9 × 0.8 ＝ 3,000 × 0.72 ＝ 2,160円
　（合計では28%引きになる。30%引きではない！）

━━━━━━━━━━━━━━━━━━━
■ 例題④：定価を求める問題
━━━━━━━━━━━━━━━━━━━
ある商品を定価の12%引きで売ると3,168円だった。定価はいくら？

【解法】
定価 × (1 − 0.12) ＝ 3,168
定価 × 0.88 ＝ 3,168
定価 ＝ 3,168 ÷ 0.88 ＝ 3,600円

★ 「割引後の価格÷残りの割合」で定価が求まる。`,
