        body: `食塩水は割合の「見えない基準量」を使う問題。「食塩の量を先に計算」するのが絶対のルールです。

━━━━━━━━━━━━━━━━━━━
■ 基本公式
━━━━━━━━━━━━━━━━━━━
　濃度(%) ＝ (食塩の重さ ÷ 食塩水全体の重さ) × 100

変形して：
　食塩の重さ ＝ 食塩水の重さ × 濃度 ÷ 100
　食塩水の重さ ＝ 食塩の重さ ÷ 濃度 × 100

━━━━━━━━━━━━━━━━━━━
■ 例題①：混合問題
━━━━━━━━━━━━━━━━━━━
6%の食塩水200gと10%の食塩水300gを混ぜると何%か？

【解法】
食塩量 ＝ 200 × 0.06 ＋ 300 × 0.10 ＝ 12 ＋ 30 ＝ 42g
全体量 ＝ 200 ＋ 300 ＝ 500g
濃度  ＝ 42 ÷ 500 × 100 ＝ 8.4%

★ ポイント：「濃度が6%と10%だから平均8%だろう」は誤り！
　重さが違うので単純平均はできない。重みつき平均（加重平均）になる。

━━━━━━━━━━━━━━━━━━━
■ 例題②：水を加える・蒸発させる
━━━━━━━━━━━━━━━━━━━
12%の食塩水150gに水を□g加えて8%にしたい。何g加えるか？

【解法】
食塩の量は変わらない！
食塩 ＝ 150 × 0.12 ＝ 18g
8%の食塩水における全体量 ＝ 18 ÷ 0.08 ＝ 225g
加えた水 ＝ 225 − 150 ＝ 75g

━━━━━━━━━━━━━━━━━━━
■ 例題③：蒸発させる問題
━━━━━━━━━━━━━━━━━━━
5%の食塩水400gから水を蒸発させて8%にした。何g蒸発させたか？

【解法】
食塩の量 ＝ 400 × 0.05 ＝ 20g（変わらない）
8%にした後の全体量 ＝ 20 ÷ 0.08 ＝ 250g
蒸発した水 ＝ 400 − 250 ＝ 150g

━━━━━━━━━━━━━━━━━━━
■ 例題④：てんびん法（視覚的な解法）
━━━━━━━━━━━━━━━━━━━
8%と14%の食塩水を混ぜて10%にしたい。
8%:14% ＝ 何:何の割合で混ぜるか？

てんびんの原理：
　8%　　　　14%
　　　10%（支点）

　14% − 10% ＝ 4（8%側のてんびんの腕の長さ）
　10% −  8% ＝ 2（14%側のてんびんの腕の長さ）

　混ぜる比 ＝ 4:2 ＝ 2:1（腕の長さを逆にする！）
　→ 8%の食塩水:14%の食塩水 ＝ 2:1

★ てんびん法の注意：腕の長さと混ぜる量の比は「逆」になる！`,
