        heading: '1. 基本図形の面積公式まとめ',
        figureId: 'lf_sansu_08',
        body: `図形の面積公式は「なぜその式になるのか」を理解すると記憶に定着しやすく、応用もきくようになります。

■ 面積公式一覧（必須）
　三角形 = 底辺 × 高さ ÷ 2
　平行四辺形 = 底辺 × 高さ
　台形 = (上底 + 下底) × 高さ ÷ 2
　ひし形 = 対角線1 × 対角線2 ÷ 2
　正方形 = 一辺 × 一辺　（= 対角線 × 対角線 ÷ 2 でも可）
　円 = 半径 × 半径 × 3.14（π）
　おうぎ形 = 半径 × 半径 × 3.14 × 中心角 ÷ 360

■ 公式の導き方（理解で覚える）
・平行四辺形：長方形に変形すると「底辺×高さ」
・三角形：平行四辺形の半分なので「÷2」
・台形：2つの三角形に分けると上底×h/2 + 下底×h/2 = (上底+下底)×h/2
・ひし形：長方形（対角線が長辺と短辺）の面積の半分

■ よく使う数値
　円周率π = 3.14（小学算数）
　半径6cmの円の面積 = 6×6×3.14 = 113.04㎠
　半径10cmの円の面積 = 100×3.14 = 314㎠

★ ポイント：「高さ」は必ず底辺に対して垂直な長さです。斜辺を「高さ」と間違えないよう注意。台形では上底・下底のどちらを底辺にしても同じ高さです。

⚠ 注意：ひし形の面積は「辺×辺」ではありません。「対角線×対角線÷2」です。辺×辺は正方形の面積の求め方です。`,
