        heading: '1. 仕事算の考え方',
        figureId: 'lf_sansu_15',
        body: `仕事算は「全体の仕事量を1（または具体的な数）とおいて、1日（1時間）あたりの仕事量を求める」問題です。

■ 基本の考え方
全体の仕事量を「1」とおく。
Aが3日でできる仕事なら、Aの1日の仕事量 = 1÷3 = 1/3

■ 基本公式
　1日の仕事量 = 1 ÷ かかる日数
　2人で協力するときの1日の仕事量 = Aの1日 + Bの1日
　完成までの日数 = 1 ÷ （1日の仕事量の合計）

例）Aが1人で6日かかる仕事をBと一緒にやると4日で終わる。
Bだけでやると何日かかるか？

Aの1日の仕事量 = 1/6
2人の1日の仕事量 = 1/4
Bの1日の仕事量 = 1/4 - 1/6 = 3/12 - 2/12 = 1/12
Bだけでの日数 = 1 ÷ 1/12 = 12日

■ 途中から参加・離脱する問題
例）AとBで4日間協力した後、Aが抜けてBだけで残りをやった。合計10日で終了。

Aの1日の仕事量 = 1/6（上の例と同じ）、Bの1日の仕事量 = 1/12

4日間でできた仕事量 = (1/6 + 1/12) × 4 = (1/4) × 4 = 1 → 全部終わる？
→ 計算が合わない場合は条件の見直しを。

■ 仕事量を「最小公倍数」でおく方法
全体の仕事量を1ではなく最小公倍数に設定すると分数を使わずに済みます。

例）Aが6日、Bが4日でできる仕事を2人でやると何日？
全体の仕事量を12（6と4の最小公倍数）とおく
Aの1日 = 12÷6 = 2、Bの1日 = 12÷4 = 3
2人の1日 = 2+3 = 5
日数 = 12÷5 = 2.4日 = 2日と2/5日

★ ポイント：最小公倍数でおく方法は分数計算が苦手な人に特に有効です。

⚠ 注意：「1/6 + 1/4 = 1/10」は誤りです。分数の足し算は通分が必要。通分すると1/6 + 1/4 = 2/12 + 3/12 = 5/12。`,
