        body: `植木算は「間隔と本数の関係」を問う問題です。「端はあるか」「円形か直線か」で公式が変わります。

■ 3つのパターン
① 両端に木を植える（直線、両端あり）
　本数 = 間隔の数 + 1

② 片端のみに木を植える（直線、片端あり）
　本数 = 間隔の数

③ 円形に植える（端なし）
　本数 = 間隔の数

■ 具体例
例）100mの直線道路の両端を含めて10mごとに木を植える。木の本数は？
　間隔の数 = 100÷10 = 10
　本数 = 10 + 1 = 11本（両端あり）

例）円形の池の周り（周囲120m）に8mごとに木を植える。木の本数は？
　本数 = 間隔の数 = 120÷8 = 15本

■ 間隔の数から長さを求める逆算
例）40mの道に5mごとに両端含めて木を植えたら何本か？
→ 40÷5+1 = 9本

逆に「9本の木を両端に植えると間隔はいくつ？」
→ 間隔の数 = 9-1 = 8、間隔の長さ = 40÷8 = 5m

■ 階段への応用（等差の考え方）
□段の階段を登るとき、1段ずつ登れる段のパターン数（踏み方）：
植木算の考え方を応用して連続する奇数の和などに繋がります。

■ 電柱・道路標識問題
「○本目から□本目まで△mある場合、間隔はいくらか」
→ 本数の差（□-○）が間隔の数。間隔 = △÷（□-○）

★ ポイント：植木算は「本数」と「間隔の数」の関係で迷ったとき、小さな例（5本、4間隔など）で手で書いて確認するのが一番確実です。

⚠ 注意：「両端」の言葉に注意。「両端を含む」→本数=間隔+1、「両端を除く」→本数=間隔-1。`,
