        heading: '★ MAXレベル：確率の基礎と組み合わせ応用',
        body: `■ 確率の定義
確率 = （求める場合の数）÷（全体の場合の数）

全事象が「同様に確からしい（どの場合も同じ起こりやすさ）」ことが前提です。

■ コインの確率
1枚のコインを3回投げる。表が2回以上出る確率は？

全体の場合の数：2³ = 8通り（表表表、表表裏、...）

表が2回以上の場合：
　表2回裏1回：C(3,2) = 3通り（どの1回が裏か）
　表3回裏0回：1通り
　合計：4通り

確率 = 4/8 = 1/2

■ サイコロの確率
2個のサイコロを投げる。目の和が7になる確率は？

全体：6×6 = 36通り
和が7の組み合わせ：(1,6)(2,5)(3,4)(4,3)(5,2)(6,1) = 6通り
確率 = 6/36 = 1/6

■ 余事象（逆から考える）
「少なくとも1回当たる」確率は「1 - 1回も当たらない確率」で計算すると簡単。

例）当たり確率1/5のクジを3回引く。少なくとも1回当たる確率は？
　1回も当たらない確率：(4/5)³ = 64/125
　少なくとも1回当たる確率：1 - 64/125 = 61/125

■ 条件付き確率の初歩
「Aが起きたという条件のもとでBが起きる確率」

例）赤玉3個、白玉2個の袋から2個取り出す。
　1個目が赤のとき、2個目も赤である確率は？
　（取り出した玉は戻さない）
　条件：1個目が赤（残りは赤2、白2の4個）
　2個目が赤の確率 = 2/4 = 1/2

★ ポイント：確率の問題は「全体を書き出す→数える」が基本。組み合わせが多い場合は「C(n,r)」を使って計算しますが、10通り以下なら必ず樹形図や表で確認することをお勧めします。

⚠ 注意：確率の答えは必ず「0以上1以下」。計算結果が1を超えたら計算ミスです。また確率の分母は「全事象の数（同様に確からしい場合の数）」であることを忘れずに。`,
