        figureId: 'lf_sansu_25',
        body: `直方体の水そうに水を入れる問題は、体積と割合を組み合わせた入試頻出テーマです。

━━━━━━━━━━━━━━━━━━━
■ 基本の考え方
━━━━━━━━━━━━━━━━━━━
水そうに入った水の体積 ＝ 底面積 × 水の深さ

だから：
　水の深さ ＝ 水の体積 ÷ 底面積
　水の体積 ＝ 底面積 × 水の深さ

★ 水面はいつも水平。底面積が一定なら、水の深さは体積に比例します。

━━━━━━━━━━━━━━━━━━━
■ 例題①：水の深さを求める
━━━━━━━━━━━━━━━━━━━
たて20cm、よこ30cmの直方体の水そうに、
体積3,600cm³の水を入れると水の深さは？
　底面積 ＝ 20 × 30 ＝ 600cm²
　深さ ＝ 3,600 ÷ 600 ＝ 6cm

━━━━━━━━━━━━━━━━━━━
■ 例題②：おもりを沈める
━━━━━━━━━━━━━━━━━━━
たて10cm、よこ10cm、高さ20cmの水そうに水が12cmの深さで入っている。
ここに1辺5cmの立方体のおもりを完全に沈めると、水面は何cm上がるか？

【解法】
おもりの体積 ＝ 5×5×5 ＝ 125cm³
この分だけ水が押し上げられる。
上がる深さ ＝ 125 ÷ (10×10) ＝ 125 ÷ 100 ＝ 1.25cm

━━━━━━━━━━━━━━━━━━━
■ 例題③：一定の割合で水を入れる（グラフ問題）
━━━━━━━━━━━━━━━━━━━
毎分600cm³の割合で、底面積300cm²の水そうに水を入れる。
6分後の水の深さは？
　6分間の水の体積 ＝ 600 × 6 ＝ 3,600cm³
　深さ ＝ 3,600 ÷ 300 ＝ 12cm

★ 発展：水そうの中に仕切り板があると、深さと時間のグラフが「途中で傾きが変わる折れ線」になります。傾きが変わる点は「仕切りの高さを水がこえた瞬間」です。

━━━━━━━━━━━━━━━━━━━
■ 例題④：水そうをかたむける
━━━━━━━━━━━━━━━━━━━
水そうをかたむけて水をこぼす問題では、残った水の形が
「三角柱」や「台形柱」になります。断面の面積を求めてから
「断面積 × 奥行き」で体積を計算します。

⚠ 注意：おもりを沈めても水そうからあふれない範囲かを必ず確認！あふれる場合は「あふれた水の量」を別に考えます。おもりが水面から出ている場合は、水につかっている部分の体積だけで計算します。`,
