        heading: '1. 単位量あたりの大きさとは',
        figureId: 'lf_sansu_38',
        body: `「単位量あたりの大きさ」とは、"1つぶんの量にそろえて比べる" という考え方です。大きさや人数がバラバラな2つのものを、そのままでは比べられません。そこで「1km²あたり」「1㎡あたり」のようにそろえて比べます。

━━━━━━━━━━━━━━━━━━━
■ 身近な「単位量あたりの大きさ」
━━━━━━━━━━━━━━━━━━━
① 人口密度　　→ 1km²あたりの人数
② こみぐあい　→ 1㎡あたりの人数
③ 速さ　　　　→ 1時間（1分・1秒）あたりに進む距離
④ 燃費　　　　→ ガソリン1Lあたりに走れる距離
⑤ 単価　　　　→ 1個あたりの値段
⑥ 仕事の効率　→ 1人が1時間にできる仕事量

━━━━━━━━━━━━━━━━━━━
■ 基本公式
━━━━━━━━━━━━━━━━━━━
　単位量あたりの大きさ ＝ 比べる量 ÷ 単位のもとになる量

━━━━━━━━━━━━━━━━━━━
■ 例題①：人口密度
━━━━━━━━━━━━━━━━━━━
A市は人口12万人、面積60km²。B市は人口18万人、面積45km²。
どちらが混んでいるか（人口密度が高いか）？

【解法】
　A市の人口密度 ＝ 120,000 ÷ 60 ＝ 2,000人/km²
　B市の人口密度 ＝ 180,000 ÷ 45 ＝ 4,000人/km²
　→ B市の方が混んでいる（A市の2倍の人口密度）

★ 人口だけを見るとB市（18万人）はA市（12万人）よりわずかに多いだけですが、面積で割ると混みぐあいの差がはっきり見えます。

━━━━━━━━━━━━━━━━━━━
■ 逆にそろえる方法（1人あたりの面積）
━━━━━━━━━━━━━━━━━━━
同じ比較を「1人あたりの面積」でもできます。この場合は数値が小さいほど混んでいることになるので注意しましょう。

　A市：1人あたり 60÷120,000 ＝ 0.0005km²
　B市：1人あたり 45÷180,000 ＝ 0.00025km²
　→ 1人あたりの面積が狭いB市の方が混んでいる（結論は同じ）

★ どちらの単位量で比べても結論は同じですが、「多いほど混む」か「少ないほど混む」かが逆になります。答えるときは言葉づかいに注意しましょう。

⚠ 注意：「人口が多い方が混んでいる」は誤りです。面積が違うと比較できません。必ず単位量（1km²・1人など）にそろえてから比べてください。`,
