        body: `単位量あたりの大きさの文章題は、求めるものによって式の形が変わります。パターンを整理しましょう。

━━━━━━━━━━━━━━━━━━━
■ パターン①：単位量あたりの大きさを求める
━━━━━━━━━━━━━━━━━━━
　単位量あたり ＝ 比べる量 ÷ 単位のもとになる量

例）米240kgを15人で等しく分けると1人あたり何kgか？
　240 ÷ 15 ＝ 16kg

━━━━━━━━━━━━━━━━━━━
■ パターン②：全体の量を求める
━━━━━━━━━━━━━━━━━━━
　全体の量 ＝ 単位量あたり × 単位のもとになる量

例）1㎡あたり0.2人が住む地域で、面積350㎡なら何人住んでいるか？
　0.2 × 350 ＝ 70人

━━━━━━━━━━━━━━━━━━━
■ パターン③：単位のもとになる量を求める
━━━━━━━━━━━━━━━━━━━
　単位のもとになる量 ＝ 全体の量 ÷ 単位量あたり

例）ある町の人口密度は250人/km²で、人口が20,000人のとき、面積は何km²か？
　20,000 ÷ 250 ＝ 80km²

━━━━━━━━━━━━━━━━━━━
■ パターン④：単位量あたりの大きさどうしの比較（順位づけ）
━━━━━━━━━━━━━━━━━━━
例）3つの工場の生産効率（1時間あたりの生産数）を比べて順位をつける問題では、
すべてを「1時間あたり」にそろえてから大小を比べます。

　工場X：480個 ÷ 6時間 ＝ 80個/時
　工場Y：525個 ÷ 7時間 ＝ 75個/時
　工場Z：440個 ÷ 5時間 ＝ 88個/時
　→ 効率のよい順：Z＞X＞Y

★ ポイント：4つのパターンとも「単位量あたり＝比べる量÷単位のもとになる量」という同じ式の変形です。何を求めるかによって、割り算の向きだけを変えます。

⚠ 注意：単位のもとになる量を求めるとき「単位量あたり×全体量」としてしまう間違いが多い。求めたいものを式の左側に置き、割合の三角形と同じ発想で「÷」の向きを確認しましょう。`,
