        body: `単位量あたりの大きさの計算では、単位換算の正確さが命です。長さ・面積・体積・重さ・時間の換算を完全に覚えましょう。

━━━━━━━━━━━━━━━━━━━
■ 長さの単位
━━━━━━━━━━━━━━━━━━━
　1km ＝ 1,000m　　1m ＝ 100cm　　1cm ＝ 10mm

━━━━━━━━━━━━━━━━━━━
■ 面積の単位（辺の換算を2回かける）
━━━━━━━━━━━━━━━━━━━
　1m² ＝ 100cm × 100cm ＝ 10,000cm²
　1km² ＝ 1,000m × 1,000m ＝ 1,000,000m²
　1a（アール）＝ 10m × 10m ＝ 100m²
　1ha（ヘクタール）＝ 100m × 100m ＝ 10,000m²

━━━━━━━━━━━━━━━━━━━
■ 体積の単位（辺の換算を3回かける）
━━━━━━━━━━━━━━━━━━━
　1m³ ＝ 100cm × 100cm × 100cm ＝ 1,000,000cm³
　1L ＝ 1,000mL ＝ 1,000cm³（1cm³＝1mLと覚える）
　1kL ＝ 1,000L ＝ 1m³

━━━━━━━━━━━━━━━━━━━
■ 重さの単位
━━━━━━━━━━━━━━━━━━━
　1t（トン）＝ 1,000kg　　1kg ＝ 1,000g　　1g ＝ 1,000mg

━━━━━━━━━━━━━━━━━━━
■ 時間の単位
━━━━━━━━━━━━━━━━━━━
　1時間 ＝ 60分　　1分 ＝ 60秒　　1日 ＝ 24時間

━━━━━━━━━━━━━━━━━━━
■ 換算の方向のルール
━━━━━━━━━━━━━━━━━━━
　大きい単位 → 小さい単位：掛け算（数値が大きくなる）
　小さい単位 → 大きい単位：割り算（数値が小さくなる）

例）3.5km を m に直す → 3.5 × 1,000 ＝ 3,500m
例）4,200mL を L に直す → 4,200 ÷ 1,000 ＝ 4.2L

━━━━━━━━━━━━━━━━━━━
■ 複合単位の換算（応用）
━━━━━━━━━━━━━━━━━━━
例）2.4m² を cm² に直す → 2.4 × 10,000 ＝ 24,000cm²
例）0.6m³ を L に直す → 0.6m³ ＝ 600L（1m³＝1,000L）

★ ポイント：面積は2回、体積は3回、単位換算の倍率をかける（または割る）。「何回かけるか」を辺・面・体で意識すると迷いません。

⚠ 注意：1m²＝100cm²と誤解する人が非常に多い。正しくは1m²＝10,000cm²（100×100）です。図をかいて確認する習慣をつけましょう。`,
