        body: `反比例は比例の逆の性質を持つ関係です。「増えると減る」関係をきちんと区別しましょう。

━━━━━━━━━━━━━━━━━━━
■ 反比例の定義
━━━━━━━━━━━━━━━━━━━
2つの量xとyがあり、xが2倍、3倍、…になると、yが1/2倍、1/3倍、…になるとき、
「yはxに反比例する」といいます。

━━━━━━━━━━━━━━━━━━━
■ 反比例の式
━━━━━━━━━━━━━━━━━━━
　x × y ＝ 決まった数
　（xとyの積が常に一定になる）

反比例の決まった数（積）の求め方：
　決まった数 ＝ x × y（どの組でも同じ値）

━━━━━━━━━━━━━━━━━━━
■ 例題①：表から反比例の式を求める
━━━━━━━━━━━━━━━━━━━
x： 2　3　4　6
y： 6　4　3　2

　x×y はどこも12 → 決まった数は12
　式：x × y ＝ 12（y ＝ 12÷x とも書ける）

━━━━━━━━━━━━━━━━━━━
■ 反比例のグラフ
━━━━━━━━━━━━━━━━━━━
反比例のグラフは、原点を通らず、x軸・y軸に限りなく近づきながらも触れない曲線（双曲線）になります。

━━━━━━━━━━━━━━━━━━━
■ 身近な反比例の例
━━━━━━━━━━━━━━━━━━━
① 決まった仕事量を仕上げるときの人数と日数（人数 × 日数 ＝ 一定）
② 決まった道のりを進むときの速さと時間（速さ × 時間 ＝ 一定）
③ 長方形の面積が一定のときの、たてとよこの長さ（たて × よこ ＝ 一定）

★ ポイント：反比例では「一方が大きくなるほど、もう一方は小さくなる」。式は必ず「積が一定」で表せます。

⚠ 注意：「xが2増えたらyが2減る」は反比例ではありません（それは和差算の関係）。反比例は「2倍・3倍になったら1/2倍・1/3倍になる」という掛け算の関係です。`,
