        heading: '★ MAXレベル：比例・反比例の複合問題',
        body: `難関校では、比例・反比例を身近な題材（歯車・グラフ・単位換算）と組み合わせた問題が出ます。

━━━━━━━━━━━━━━━━━━━
■ 難問①：歯車の回転数（反比例の応用）
━━━━━━━━━━━━━━━━━━━
歯数24の歯車Aと、歯数16の歯車Bがかみ合っている。
Aが3回転する間に、Bは何回転するか。

【解法】
かみ合う歯車では「歯数×回転数」がAとBで等しくなる（かみ合った歯の数が同じだから）。
　Aの歯の移動数 ＝ 24 × 3 ＝ 72
　Bの回転数 ＝ 72 ÷ 16 ＝ 4.5回転

★ 歯数と回転数は反比例の関係（歯数が少ないほど、同じ距離をかみ合うのに多く回転する）。

━━━━━━━━━━━━━━━━━━━
■ 難問②：反比例のグラフ上の長方形の面積
━━━━━━━━━━━━━━━━━━━
反比例のグラフ上に点(2,6)と点(4,3)がある。それぞれの点からx軸・y軸に垂線をおろして
できる長方形の面積を比べるとどうなるか。

【解法】
　点(2,6)がつくる長方形の面積 ＝ 2×6 ＝ 12
　点(4,3)がつくる長方形の面積 ＝ 4×3 ＝ 12
　→ 反比例のグラフ上のどの点でも、この長方形の面積は「決まった数」と等しく、常に12で一定

★ 反比例のグラフの性質：x×y＝決まった数 なので、この長方形の面積はグラフ上のどこでも変わりません。

━━━━━━━━━━━━━━━━━━━
■ 難問③：一定の速さのグラフから比例定数を求める
━━━━━━━━━━━━━━━━━━━
ある自動車が一定の速さで走り、2時間で140km進んだ。この車が5時間で進む道のりは何kmか。

【解法】
　比例定数（時速）＝ 140 ÷ 2 ＝ 70km/h
　5時間で進む道のり ＝ 70 × 5 ＝ 350km

━━━━━━━━━━━━━━━━━━━
■ 難問④：蛇口の本数と満水までの時間（反比例）
━━━━━━━━━━━━━━━━━━━
同じ性能の蛇口3本で水そうを満水にするのに40分かかる。
蛇口を5本使うと何分で満水になるか。

【解法】
　全体の水の量に相当する値（本数×時間）＝ 3 × 40 ＝ 120
　5本での時間 ＝ 120 ÷ 5 ＝ 24分

★ ポイント：比例・反比例の複合問題では、まず「何が一定に保たれるか」（速さ・全体量・面積・かみ合う歯の数など）を見つけることが解法の第一歩です。

⚠ 注意：歯車の問題は「回転数が歯数に反比例する」だけを覚えるのではなく、「歯数×回転数＝かみ合った歯の総数」という意味を理解しておくと、応用問題にも対応できます。`,
