        heading: '4. つるかめ算の総復習と3種類のつるかめ算',
        figureId: 'lf_sansu_53',
        body: `つるかめ算は「2種類のものが混ざっている」ときの基本解法です。3種類以上になった場合の対処法を身につけましょう。

━━━━━━━━━━━━━━━━━━━
■ つるかめ算の基本（2種類）復習
━━━━━━━━━━━━━━━━━━━
全部を片方と仮定し、実際との差を「1つあたりの差」で割ると、もう一方の数がわかります。

例）鶴と亀が合わせて15匹、足の合計が44本のとき、それぞれ何匹か。
　全部鶴（2本足）と仮定 ＝ 2×15＝30本
　実際との差 ＝ 44−30＝14本
　1匹を亀に変えると4−2＝2本増える
　亀 ＝ 14÷2＝7匹、鶴 ＝ 15−7＝8匹

━━━━━━━━━━━━━━━━━━━
■ 3種類のつるかめ算 — 条件で2種類に帰着させる
━━━━━━━━━━━━━━━━━━━
3種類のものが混ざっているときは、追加の条件（「〇〇の数は△△の2倍」など）を使って
2種類の関係にまとめてから、通常のつるかめ算を使います。

━━━━━━━━━━━━━━━━━━━
■ 例題①：3種類の果物のつるかめ算
━━━━━━━━━━━━━━━━━━━
りんご（100円）、みかん（60円）、かき（140円）を合わせて15個買い、
代金の合計は1,500円だった。かきの数はりんごの数の2倍であるとき、それぞれ何個買ったか。

【解法】
　りんごの数をaとすると、かきの数は2a、みかんの数をbとする。
　個数の式：a ＋ 2a ＋ b ＝ 15 → 3a ＋ b ＝ 15 …①
　代金の式：100a ＋ 60b ＋ 140×2a ＝ 1,500 → 380a ＋ 60b ＝ 1,500 …②

　①×60：180a ＋ 60b ＝ 900 …①'
　②−①'：200a ＝ 600 → a ＝ 3
　①に代入：9＋b＝15 → b＝6
　りんご ＝ 3個、みかん ＝ 6個、かき ＝ 2×3＝6個
　検算：個数 3＋6＋6＝15 ✓、代金 100×3＋60×6＋140×6＝300＋360＋840＝1,500 ✓

★ ポイント：3種類のつるかめ算は「1種類を他の1種類の倍数で表す」条件を見つけて2文字に減らすのが定石です。

⚠ 注意：3種類のまま連立方程式を作ろうとすると式が足りません（式は2本しか作れないのに文字が3つ）。必ず追加の条件を使って文字を減らしましょう。`,
