        body: `うそつき算は、「誰が本当のことを言っていて、誰がうそをついているか」を条件から見抜く問題です。仮定法で1人ずつ確かめるのが基本です。

━━━━━━━━━━━━━━━━━━━
■ うそつき算の基本戦略
━━━━━━━━━━━━━━━━━━━
①「この人が正直者（またはうそつき）だ」と仮定する
②その仮定のもとで、他の人の発言が矛盾なく成り立つか確認する
③矛盾が出たら仮定を変えてやり直す

━━━━━━━━━━━━━━━━━━━
■ 例題①：1人だけが正直者
━━━━━━━━━━━━━━━━━━━
A、B、Cの3人のうち1人だけが正直者で、残り2人はうそつきである。
　A「私は正直者だ」
　B「Aはうそつきだ」
　C「Bはうそつきだ」
正直者は誰か。

【解法（仮定法）】
　Aが正直者と仮定 → Aの発言は本当。Bの発言「Aはうそつき」は誤り→Bもうそつき（矛盾なし）。
　Cの発言「Bはうそつき」は本当のはず→Cも正直者になってしまい、正直者が2人になり矛盾。

　Bが正直者と仮定 → 「Aはうそつき」は本当→Aはうそつき（Aの発言「私は正直者」はうそで整合）。
　Cの発言「Bはうそつき」はうそのはず（Cはうそつきなので）→実際Bは正直者なので整合する。
　→ 正直者はBの1人だけで矛盾なし ✓

　Cが正直者と仮定すると、同様に確認すると矛盾が生じる（各自で確認してみましょう）。

　→ 正直者はB

★ ポイント：仮定して矛盾が出ないかを最後まで確認することが大切です。矛盾が出た仮定はすぐに捨てて次の仮定に移りましょう。

⚠ 注意：うそつきの発言は「内容がすべて逆」になります。「Aはうそつきだ」という発言がうそなら「Aは正直者だ」という意味になる、という論理の反転を正確に扱いましょう。`,
