        heading: '4. 覆面算・虫食い算',
        body: `覆面算は、同じ文字（記号）が同じ数字を表すという約束のもとで、計算式を成立させる数字を求める問題です。位ごとのくり上がりに注目するのがコツです。

━━━━━━━━━━━━━━━━━━━
■ 覆面算の基本ルール
━━━━━━━━━━━━━━━━━━━
・同じ文字は同じ数字
・違う文字は違う数字（特に指定がなければ）
・最上位の文字は0にならない

━━━━━━━━━━━━━━━━━━━
■ 虫食い算（一部の数字が隠れている筆算）
━━━━━━━━━━━━━━━━━━━
　　3□7
×　　　6
─────
　2 2 □ 2

このような虫食い算は、わかっている位から逆算していきます。

【解法の手順】
①一の位：7×6＝42 → 一の位は2、くり上がり4 → 答えの一の位「□」は2で確定
②十の位：□×6＋4（くり上がり）の一の位が2になる□を探す
③百の位・千の位の計算と、答えの「2 2」の部分と整合するかを確認して絞り込む

━━━━━━━━━━━━━━━━━━━
■ 例題：文字を含む足し算の覆面算
━━━━━━━━━━━━━━━━━━━
　A 3 8
＋ 2 B 4
─────
　7 6 2

AとBにあてはまる数字を求めよ。

【解法】
　一の位：8＋4＝12 → 一の位2、くり上がり1（答えの一の位2と一致）
　十の位：3＋B＋1（くり上がり）＝6、または16（さらにくり上がる場合）
　　まず繰り上がりなしで試す：3＋B＋1＝6 → B＝2
　百の位：A＋2＝7 → A＝5（くり上がりなしの場合）
　検算：538＋224＝762 ✓
　→ A＝5、B＝2

★ ポイント：覆面算・虫食い算は「一の位から順に」計算し、くり上がりを次の位に必ず持ち越すことが鉄則です。

⚠ 注意：くり上がりの有無で答えの候補が変わります。1通りに決まらない場合は、くり上がりがある場合とない場合の両方を試して、条件（同じ文字は同じ数字など）に合う方を選びましょう。`,
