        body: `魔方陣は、正方形のマスに数を並べて、たて・よこ・ななめのどの列を足しても同じ数になるようにしたものです。

━━━━━━━━━━━━━━━━━━━
■ 3×3の魔方陣（最も基本的な形）
━━━━━━━━━━━━━━━━━━━
1から9までの数字を3×3のマスに1つずつ入れて、
たて・よこ・ななめの3つの数の和がすべて等しくなるようにします。

━━━━━━━━━━━━━━━━━━━
■ 各列の和を求める
━━━━━━━━━━━━━━━━━━━
1から9までの合計 ＝ 45
3列あるので、1列の和 ＝ 45 ÷ 3 ＝ 15

━━━━━━━━━━━━━━━━━━━
■ 中心のマスに入る数
━━━━━━━━━━━━━━━━━━━
中心のマスは、たて・よこ・ななめの4つの列すべてに共通して使われます。
このことから、3×3の魔方陣の中心には必ず「5」（1〜9の平均）が入ることが知られています。

━━━━━━━━━━━━━━━━━━━
■ 完成した3×3魔方陣の例
━━━━━━━━━━━━━━━━━━━
　4　9　2
　3　5　7
　8　1　6

　たて：4+3+8=15、9+5+1=15、2+7+6=15
　よこ：4+9+2=15、3+5+7=15、8+1+6=15
　ななめ：4+5+6=15、2+5+8=15
　→ すべて15で一致 ✓

━━━━━━━━━━━━━━━━━━━
■ 魔方陣の応用問題
━━━━━━━━━━━━━━━━━━━
【例】3×3の魔方陣で、四隅の数の和はいくらか（上の例で確認せよ）。
　4＋2＋8＋6＝20

★ ポイント：魔方陣の問題では「1列の和（この場合15）」を最初に求めることが、空欄を埋める手がかりになります。

⚠ 注意：4×4以上の魔方陣は、3×3とは違う作り方が必要です。中学受験では3×3の魔方陣が中心ですが、規則を発見する力が問われる発展問題として4×4が出ることもあります。`,
