        body: `図形の問題でも比の考え方は大活躍します。「高さが共通なら面積比＝底辺の比」という関係を使いこなしましょう。

━━━━━━━━━━━━━━━━━━━
■ 図形の比の基本性質
━━━━━━━━━━━━━━━━━━━
・高さが共通の三角形どうしは、面積比＝底辺の比
・底辺が共通の三角形どうしは、面積比＝高さの比

━━━━━━━━━━━━━━━━━━━
■ 例題①：底辺の比から面積比を求める
━━━━━━━━━━━━━━━━━━━
三角形ABCで、辺BC上の点DがBD:DC＝3:2となる位置にある。△ABDと△ADCの面積比は？

【解法】
　底辺BD、DCの比がそのまま面積比になる（高さ＝頂点Aから直線BCまでの距離が共通）
　△ABD:△ADC ＝ 3:2

━━━━━━━━━━━━━━━━━━━
■ 例題②：面積比から底辺の比を逆算する
━━━━━━━━━━━━━━━━━━━
三角形ABCの面積が40cm²で、辺BC上の点Eによって△ABEの面積が24cm²になった。BE:ECを求めよ。

【解法】
　△AECの面積 ＝ 40−24 ＝ 16cm²
　BE:EC ＝ △ABE:△AEC ＝ 24:16 ＝ 3:2

━━━━━━━━━━━━━━━━━━━
■ 例題③：2つの比の複合
━━━━━━━━━━━━━━━━━━━
三角形ABCで、辺AB上の点Pが AP:PB＝2:3、辺AC上の点QがAQ:QC＝1:2 の位置にある。
三角形APQの面積は、三角形ABCの面積の何倍か。

【解法】
　△APQと△ABCは頂点Aを共有し、
　△APQ ＝ △ABC × (AP/AB) × (AQ/AC)
　＝ △ABC × (2/5) × (1/3)
　＝ △ABC × 2/15

★ ポイント：頂点を共有する三角形の面積比は「2辺の比の積」で求められます。

⚠ 注意：「AP:PB＝2:3」のとき、AP/ABは2/5であって2/3ではありません。分母を「比の合計」にすることを忘れないようにしましょう。`,
