        body: `年齢の比や分配の比が絡む問題では、「何が変わらないか」を先に見抜くことが最大のポイントです。

━━━━━━━━━━━━━━━━━━━
■ 年齢の比の文章題
━━━━━━━━━━━━━━━━━━━
年齢は毎年みんな平等に1歳ずつ増えるので、「年齢の差」は何年たっても変わりません。

━━━━━━━━━━━━━━━━━━━
■ 例題①：現在の比から将来の比へ
━━━━━━━━━━━━━━━━━━━
父と子の年齢の比は現在9:2で、父は45歳である。子の年齢が父の年齢の半分になるのは何年後か。

【解法】
　比から子の現在の年齢 ＝ 45×2/9 ＝ 10歳
　年齢の差 ＝ 45−10 ＝ 35歳（一定）
　x年後に父の年齢＝子の年齢×2
　(45＋x) ＝ 2×(10＋x)
　45＋x ＝ 20＋2x
　x ＝ 25
　→ 25年後（このとき父70歳、子35歳で確かに2倍）

━━━━━━━━━━━━━━━━━━━
■ 例題②：過去の比から現在を求める
━━━━━━━━━━━━━━━━━━━
現在の母と娘の年齢の比は7:3。5年前は比が3:1だった。現在の母の年齢は？

【解法】
　M＝7k、D＝3kとおく（現在の比から）
　5年前：(7k−5):(3k−5) ＝ 3:1
　7k−5 ＝ 3(3k−5) ＝ 9k−15
　10 ＝ 2k → k ＝ 5
　現在の母 ＝ 7×5 ＝ 35歳

━━━━━━━━━━━━━━━━━━━
■ 分配比の融合問題
━━━━━━━━━━━━━━━━━━━
【例】兄弟3人でお年玉を3:2:1の比で分けたが、その後長男が次男に500円渡したところ、
長男と次男の金額が同じになった。お年玉の合計はいくらか。

【解法】
　1あたりをkとおくと、長男3k、次男2k、三男k
　長男が次男に500円渡すと：長男(3k−500)＝次男(2k＋500)
　3k−500 ＝ 2k＋500
　k ＝ 1,000
　合計 ＝ (3＋2＋1)×1,000 ＝ 6,000円

★ ポイント：年齢の比の文章題は「差が一定」、分配の比の文章題は「渡す・もらうと合計は不変、差は変化する」という性質を使い分けます。

⚠ 注意：年齢の比の過去・未来の問題は、必ず「年齢の差が変わらない」ことを軸に式を立てます。比の値がそのまま年齢だと勘違いしないよう、1あたりの値（k）をおいて計算しましょう。`,
