        body: `階差数列は、「となりどうしの差（階差）」自体が規則的に変化する数列です。階差の和を使って元の数列の項を求めます。

━━━━━━━━━━━━━━━━━━━
■ 階差数列の考え方
━━━━━━━━━━━━━━━━━━━
数列 1, 2, 4, 7, 11, 16, … を見ると、
　差は 1, 2, 3, 4, 5, … と規則的に増えている（階差数列）

━━━━━━━━━━━━━━━━━━━
■ 例題①：階差から次の項を求める
━━━━━━━━━━━━━━━━━━━
数列 1, 2, 4, 7, 11, 16, … の次の項（第7項）は？

【解法】
　直前までの階差は 1,2,3,4,5 → 次の階差は6
　第7項 ＝ 16＋6 ＝ 22

━━━━━━━━━━━━━━━━━━━
■ 例題②：階差数列の和を使って離れた項を求める
━━━━━━━━━━━━━━━━━━━
数列 3, 5, 9, 15, 23, … の第10項を求めよ（階差が2,4,6,8,…と増えていく）。

【解法】
　階差は 2,4,6,8,10,12,14,16,18（第1項から第10項までの9個の階差）
　第10項 ＝ 第1項(3) ＋ 階差の合計(2＋4＋6＋…＋18)

　階差の合計 ＝ 等差数列の和 ＝ 9×(2＋18)÷2 ＝ 9×10 ＝ 90
　第10項 ＝ 3＋90 ＝ 93

━━━━━━━━━━━━━━━━━━━
■ 階差数列とグラフの関係
━━━━━━━━━━━━━━━━━━━
階差数列は、もとの数列を「グラフにしたときの傾きの変化」を表しているとも考えられます。
階差が一定なら等差数列（直線的な変化）、階差が変化するなら曲線的な変化になります。

★ ポイント：階差数列の問題は「階差の数列自体にどんな規則があるか」を見抜き、その規則性（等差数列であることが多い）を利用して和を計算するのが定石です。

⚠ 注意：第n項を求めるとき、必要な階差の個数は「n−1個」です（第1項から第n項までの間には、階差がn−1回登場します）。個数を1つ多く（少なく）数えるミスに注意しましょう。`,
